function kanaUnitCards(deck){const source=deck==="hiragana"?hiragana:katanaka;return source.map(k=>({jp:k.kana,reading:k.roumaji,key:"kana:"+deck+":"+k.kana,answers:[k.roumaji],kanaType:k.type,deck,unitKey:"kana-"+deck,jlpt:null}))}
function kanaMastery(deck){return unitMastery(kanaUnitCards(deck))}
function katakanaUnlocked(){return kanaMastery("hiragana")>=.8}
function kanjiUnlocked(){return katakanaUnlocked()&&kanaMastery("katakana")>=.8}
function jlptLabel(level){return level?"JLPT N"+level:"No official JLPT level"}
// Normalize accents/case/punctuation and tolerate a single typo for most short answers.
function norm(s){return String(s).normalize("NFD").replace(/([\p{Script=Latin}])\p{M}+/gu,"$1").toLocaleLowerCase().replace(/ß/g,"ss").replace(/～/g,"").replace(/[^\p{L}\p{N}]+/gu," ").trim().replace(/\s+/g," ")}
function distance(a,b){const prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let diagonal=prev[0];prev[0]=i;for(let j=1;j<=b.length;j++){const old=prev[j];prev[j]=Math.min(prev[j]+1,prev[j-1]+1,diagonal+(a[i-1]===b[j-1]?0:1));diagonal=old}}return prev[b.length]}
function matches(input,answers){const v=norm(input);if(!v)return false;return answers.some(a=>{const target=norm(a);if(v===target)return true;if(Math.min(v.length,target.length)<5)return false;return distance(v,target)<= (Math.max(v.length,target.length)>=9?2:1)})}
function findTypoMatch(input,answers){const value=norm(input);if(!value)return null;let best=null;for(const answer of answers||[]){if(typeof answer!=="string"||/[\\u3040-\\u30ff\\u3400-\\u9fff]/u.test(answer))continue;const target=norm(answer);if(!target||value===target||Math.min(value.length,target.length)<4)continue;const d=distance(value,target);if(d===1&&(!best||target.length>best.target.length))best={target:answer,distance:d}}return best}
function showTypoFeedback(input,expected){const el=document.getElementById("feedback");el.replaceChildren();el.className="feedback typo-feedback";el.style.whiteSpace="normal";const title=document.createElement("div");title.textContent="Se acepta como correcta, pero hay un pequeño error.";const comparison=document.createElement("div");comparison.className="typo-comparison";const makeDiff=(source,target,showExtra)=>{const a=Array.from(source),b=Array.from(target),m=a.length,n=b.length,dp=Array.from({length:m+1},()=>Array(n+1).fill(0));for(let i=0;i<=m;i++)dp[i][0]=i;for(let j=0;j<=n;j++)dp[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(norm(a[i-1])===norm(b[j-1])?0:1));const ops=[];let i=m,j=n;while(i||j){if(i&&j&&dp[i][j]===dp[i-1][j-1]+(norm(a[i-1])===norm(b[j-1])?0:1)){ops.unshift({type:norm(a[i-1])===norm(b[j-1])?"same":"change",a:a[i-1],b:b[j-1]});i--;j--}else if(i&&dp[i][j]===dp[i-1][j]+1){ops.unshift({type:"extra",a:a[i-1]});i--}else{ops.unshift({type:"missing",b:b[j-1]});j--}}const out=document.createElement("span");out.className="typo-typed";for(const op of ops){if(op.type==="same"){out.append(document.createTextNode(op.a))}else if(op.type==="extra"){const mark=document.createElement("span");mark.className="typo-extra";mark.textContent=op.a;out.append(mark)}else if(op.type==="missing"){const mark=document.createElement("span");mark.className="typo-missing";mark.textContent=op.b;out.append(mark)}else{const mark=document.createElement("span");mark.className="typo-extra";mark.textContent=op.a;out.append(mark);const expectedMark=document.createElement("span");expectedMark.className="typo-missing";expectedMark.textContent=op.b;out.append(expectedMark)}}return out};comparison.append(makeDiff(input,expected,true));el.append(title,comparison);}
