const NEW_BATCH_SIZE=5,MASTER_STAGE=3;
const STAGE_INTERVALS=KaadoSRS.INTERVALS_DAYS;
const RANKS=[{name:"Ashigaru",min:0},{name:"Samurai",min:16},{name:"Hatamoto",min:32},{name:"Daimyō",min:48},{name:"Taishō",min:64},{name:"Shōgun",min:80},{name:"Fudō Myōō",min:100}];
const STAGE_NAMES=[{name:"Tōkatsu",jp:"等活地獄",meaning:"Hell of resurrection"},{name:"Kokujō",jp:"黒縄地獄",meaning:"Hell of black ropes"},{name:"Shūgō",jp:"衆合地獄",meaning:"Hell of crushing"},{name:"Kyōkan",jp:"叫喚地獄",meaning:"Hell of screaming"},{name:"Daikyōkan",jp:"大叫喚地獄",meaning:"Great hell of screaming"},{name:"Shōnetsu",jp:"焦熱地獄",meaning:"Scorching hell"},{name:"Daishōnetsu",jp:"大焦熱地獄",meaning:"Great scorching hell"},{name:"Muken",jp:"無間地獄",meaning:"Uninterrupted hell"}];
function selectedTopic(){return document.getElementById("topicSelect").value}
function vocabTopics(){return [...new Set(WORDS.map(w=>w.topic))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))}
function vocabUnitCards(topic){return WORDS.filter(w=>w.topic===topic).map(w=>({...w,key:w.jp,unitKey:"vocab-"+topic}))}
function kanjiUnitCards(chapter,mode){return KANJI.filter(k=>k.chapter===chapter&&(mode!=="kun"||k.kun.length>0)).map(k=>{const base={jp:k.c,reading:"",key:"kanji:"+k.c,chapter:k.chapter,kun:k.kun,on:k.on,en:k.en,es:k.es,unitKey:"kanji-"+chapter,type:"kanji"};if(mode==="kun")return {...base,answers:k.kun,mode:"kun"};if(mode==="on")return {...base,answers:k.on,mode:"on"};return {...base,mode:"translation"}})}
function unitMastery(cards,minStage=MASTER_STAGE){return cards.length?cards.filter(w=>state(w).stage>=minStage).length/cards.length:0}
function isVocabUnlocked(topic){const topics=vocabTopics(),i=topics.indexOf(topic);if(i<=0)return true;return unitMastery(vocabUnitCards(topics[i-1]))>=.8}
function isKanjiChapterUnlocked(chapter){if(!kanjiUnlocked())return false;if(chapter<=1)return true;const previous=KANJI_CHAPTERS.find(c=>c.id===chapter-1);if(!previous)return false;const cards=previous.chars.map(ch=>({key:"kanji:"+ch})).filter(card=>KANJI.some(k=>k.c===card.key.slice(6)));return unitMastery(cards)>=.8}
function unlockedVocabTopics(){return vocabTopics().filter(isVocabUnlocked)}
function unlockedKanjiChapters(){return KANJI_CHAPTERS.filter(ch=>isKanjiChapterUnlocked(ch.id)).map(ch=>ch.id)}
function releaseFilter(items){const groups=new Map();items.forEach(w=>{if(!groups.has(w.unitKey))groups.set(w.unitKey,[]);groups.get(w.unitKey).push(w)});const allowed=[];for(const cards of groups.values()){cards.forEach((w,i)=>{const batch=Math.floor(i/NEW_BATCH_SIZE);let unlocked=batch===0||state(w).seen>0;if(!unlocked){unlocked=true;for(let b=1;b<=batch;b++){const prev=cards.slice((b-1)*NEW_BATCH_SIZE,b*NEW_BATCH_SIZE);if(!prev.length||unitMastery(prev,1)<.8){unlocked=false;break}}}if(unlocked)allowed.push(w)})}return allowed}
